struct CustomInputState
{
    struct MyCustomType *data; // The custom input
    size_t cursor; // A value to keep track of the position.
};

static bool CustomAdvance(void *state)
{
    struct CustomInputState *typed_state = state;
    /* ... */
}

static char CustomGetCharacter(void *state)
{
    struct CustomInputState *typed_state = state;
    /* ... */
}

static void CustomDestroy(void *state)
{
    struct CustomInputState *typed_state = state;
    /* ... */
    free(state);
}

static const struct SilikoInputVTable vTable = {
	.advance = CustomAdvance,
	.getCharacter = CustomGetCharacter,
	.destroy = CustomDestroy
};

SilikoDataSource *CustomSourceCreate(struct MyCustomType *data)
{
    CustomInputState *state = NULL;
    if (!(state = malloc(sizeof(CustomInputState))))
		    return NULL;

    state->data = data;
    state->cursor = 0;

    SilikoDataSource *source = NULL;
    if (!(source = SilikoInputCreate(&vTable, state)))
    {
        free(state);
        return NULL;
    }
    return source;
}

const SilikoToken *token =
    SilikoLexerGetToken(lexer); // Integer:3
// Do something with token here.

SilikoLexerAdvance(lexer); // token now points to a free'd object.
token = SilikoLexerGetToken(lexer); // Character:d
// Do something with token here.

SilikoLexerAdvance(lexer); // Again, token is invalidated.
token = SilikoLexerGetToken(lexer); // Integer:6
// Do something with token here.

SilikoLexerAdvance(lexer); // Token is invalidated here, too.
token = SilikoLexerGetToken(lexer); // End of Input
// Put it all together here.

SilikoNode *operator = SilikoNodeCreateBranch("add");
SilikoNode *left_operand = SilikoNodeCreateFromInteger(2);
SilikoNode *right_operand = SilikoNodeCreateFromInteger(3);
SilikoNodePushRight(operator, left_operand);
SilikoNodePushRight(operator, right_operand);

SilikoNode *right_operand = SilikoNodeCreateFromInteger(3);
SilikoNode *left_operand = SilikoNodeCreateFromInteger(2);
SilikoNode *operator = SilikoNodeCreateBranch("add");
SilikoNodePushLeft(operator, right_operand);
SilikoNodePushLeft(operator, left_operand);

#include <stdio.h>

#include <SilikoCore/Engine.h>
#include <SilikoCore/Value.h>

SilikoValue *CustomFunctionAddTwo(int argc, SilikoValue **argv)
{
    if (argc != 1)
    return SilikoValueCreateFromError(SilikoErrorFunctionArguments);

    switch (SilikoValueGetStatus(argv[0]))
    {
    case SilikoValueInteger:
        return SilikoValueCreateFromInteger(
            SilikoValueGetInteger(argv[0]) + 2);
    case SilikoValueReal:
        return SilikoValueCreateFromReal(
            SilikoValueGetReal(argv[0]) + 2.0);
    default: // This is an error. Propagate it.
        return SilikoValueCopy(argv[0]);
    }
}

int main(int argc, char *argv[])
{
    SilikoEngine *engine = SilikoEngineCreate();
    SilikoFunction *addtwo = SilikoPureFunctionCreate(
        CustomFunctionAddTwo);

    SilikoEngineInstallFunction(engine, "addtwo", addtwo);

    SilikoValue *inputs[1];
    inputs[0] = SilikoValueCreateFromInteger(5);
    SilikoValue *result = SilikoEngineCallFunction(engine,
        "addtwo", 1, inputs);

    printf("The result is: %lld\n",
        SilikoValueGetInteger(result));

    SilikoValueDestroy(result);
    SilikoValueDestroy(inputs[0]);
    SilikoEngineDestroy(engine);
}

SilikoEngine *engine = SilikoEngineCreate();
SilikoInstallOperations(engine);
SilikoValue *result = SilikoEvaluate(engine, root_node);

SilikoEngine *engine = SilikoEngineCreate();
SilikoInstallOperations(engine);
SilikoInput *input = SilikoStringInputCreate("1d20");
SilikoNode *tree = SilikoParseInfix(input);
SilikoValue *result = SilikoEvaluate(engine, tree);
SilikoNodeDestroy(tree);

if (SilikoValueGetStatus(result) == SilikoValueInteger)
{
    if (SilikoValueGetInteger(result) >= 15)
    {
        printf("You find a secret door behind the"
            " bookcase.\n");
    }
    else
    {
        printf("There appears to be nothing of note in"
            " the library.\n");
    }
}
else
{
    fprintf(stderr, "Something went wrong.\n");
}
SilikoValueDestroy(result);
SilikoEngineDestroy(engine);
